{"code":"
const [resources, templates] = await Promise.all([
  tools.list_mcp_resources({ server: "catalog" }),
  tools.list_mcp_resource_templates({ server: "catalog" }),
]);

const text = await tools.read_mcp_resource({ server: "catalog", uri: "memo://text" });
const binary = await tools.read_mcp_resource({ server: "catalog", uri: "memo://binary" });
const greeting = await tools.read_mcp_resource({ server: "catalog", uri: "memo://greeting/reader" });

// Inspect binary contents without exposing blob data.
const contents = (binary as any)?.contents;
const first = Array.isArray(contents) ? contents[0] : undefined;
const binaryAvailable = typeof first?.blob === "string" && first.blob.length > 0;

inspect(JSON.stringify({
  resources,
  templates,
  text,
  greeting,
  binarySummary: {
    uri: first?.uri,
    mimeType: first?.mimeType,
    blobIsNonemptyString: binaryAvailable,
  },
  binaryAvailable,
}, null, 2)); return;
","description":"List catalog MCP resources and read three memos"}

